        if (evaluator.isMemberInClass(method, SYSTEM) || evaluator.isMemberInClass(method, RUNTIME)) {
            context.report(ISSUE, node, context.getLocation(node),
                    "Do not use `load` to dynamically load code; use `loadLibrary` instead");
        }
    }
}
```

